GRAPH_SHA = '298a369295935dcc2c3aa072e806ed2c3488de76167ca6cd67c2ab9c3e0ab604'
STATUS_SHA = '0ba5e2b0f0a6bd8e6c594339693e4248054d5844d05ac64034609f80dc1f56ae'
SOURCE_FREEZE_SHA = '4dd350e9efb626ed887a7a2fcf29643764c954651372d7f6b32bb6ca12fbbca6'
CORE_SHAS = ['e853de3776a74c8ddb2cccb9d0967ac1d9974c5d45fbec473837ae19c9204972']
def need(ok,message):
    if not ok:raise ValueError(message)
def sha(b):return hashlib.sha256(b).hexdigest()
def diff(a,b,old,new):
    return b''.join(difflib.diff_bytes(difflib.unified_diff,a.splitlines(True),b.splitlines(True),fromfile=old.encode(),tofile=new.encode(),n=3))
def verify(root):
    root=root.resolve();reads={}
    def read(name):
        p=PurePosixPath(name);need(not p.is_absolute() and '..' not in p.parts,'Unsafe declared input')
        path=root.joinpath(*p.parts)
        need(path.is_file() and not path.is_symlink() and path.resolve().is_relative_to(root),'Declared input missing or outside repository')
        if name not in reads:reads[name]=path.read_bytes()
        return reads[name]
    def pinned(name,digest,message):
        b=read(PACKET+'/'+name);need(sha(b)==digest,message);return json.loads(b)
    evidence=pinned('EVIDENCE_MAP.json',MAP_SHA,'Archive map changed');contents={};origins={}
    for obj in evidence['objects']:
        need(obj['sha256'] not in contents,'Duplicate archive object');z=read(PACKET+'/'+obj['path'])
        need(sha(z)==obj['stored_sha256'] and len(z)==obj['stored_bytes'],'Compressed archive changed')
        b=gzip.decompress(z);need(sha(b)==obj['sha256'] and len(b)==obj['bytes'],'Archived source changed');contents[obj['sha256']]=b
        for origin in obj['origins']:
            need(origin['path'] not in origins,'Duplicate original alias');origins[origin['path']]=obj['sha256']
    def archived(name):return contents[origins[name]]
    contract=evidence['source_package'];prefix=contract['path']+'/'
    def source(name):return archived(prefix+name)
    need(contract['freeze_sha256']==SOURCE_FREEZE_SHA and sha(source('FINAL_FREEZE.json'))==SOURCE_FREEZE_SHA,'Source freeze differs')
    seal=json.loads(source('FINAL_FREEZE.json'));members=contract['members'];extras=contract['additional_files']
    need(seal['members']==members and len(members)==contract['member_count']==142 and contract['complete_file_count']==143,'Assembly membership differs')
    need(contract['directories']==seal['directories'],'Assembly directory closure differs')
    need(len(extras)==1 and extras[0]['path']=='FINAL_FREEZE.json','Assembly extra membership differs')
    need({p for p in origins if p.startswith(prefix)}=={prefix+r['path'] for r in members+extras},'Complete assembly aliases differ')
    for r in members+extras:
        b=source(r['path']);need(sha(b)==r['sha256'] and len(b)==r['bytes'],'Assembly member differs')
    selection=json.loads(source('archive/INDEX.json'))
    need(len(selection['aliases'])==selection['alias_count']==149 and selection['unique_objects']==99,'Original alias closure differs')
    for r in selection['aliases']:
        b=source(r['object']);need(b==archived(r['source_path']) and sha(b)==r['sha256'] and len(b)==r['bytes'],'Original source alias differs')
    overlay=evidence['framing_overlay'];oprefix=overlay['path']+'/'
    def osource(name):return archived(oprefix+name)
    need(overlay['seal_sha256']=='42f2565585bd157680cd7378eeb036d2ca5a04e873beb9fffa0829d400b19bbf' and sha(osource('SOURCE_SEAL.json'))==overlay['seal_sha256'],'Framing overlay seal differs')
    oseal=json.loads(osource('SOURCE_SEAL.json'));need(oseal['members']==overlay['members'] and len(overlay['members'])==21 and overlay['complete_file_count']==22 and oseal['directories']==overlay['directories'],'Framing overlay membership differs')
    need({p for p in origins if p.startswith(oprefix)}=={oprefix+r['path'] for r in overlay['members']+overlay['additional_files']},'Framing overlay aliases differ')
    for r in overlay['members']+overlay['additional_files']:
        b=osource(r['path']);need(sha(b)==r['sha256'] and len(b)==r['bytes'],'Framing overlay member differs')
    mapping=json.loads(source('BODY_MAP.json'));old_candidate=source('CANDIDATE_NOTE.md');old_wrapper=source('wrappers/CURRENT_WRAPPER.md');b=source('cores/DERIVATION_V2.md')
    need(old_candidate==b''.join(source(x) for x in mapping['construction']) and sha(old_candidate)==mapping['candidate']['sha256'],'Original candidate does not reconstruct')
    x=mapping['candidate_body'];i,j=x['byte_start_0'],x['byte_end_exclusive']
    need(sha(b)==x['sha256']==CORE_SHAS[0] and old_candidate[i:j]==b and old_candidate.count(b)==1,'Complete original proof differs')
    need(old_candidate[:i].count(b'\n')+1==x['line_start_1'] and old_candidate[:j].count(b'\n')==x['line_end_1'],'Original extraction lines differ')
    correction=json.loads(osource('CORRECTION_MAP.json'));before=correction['before'].encode();after=correction['after'].encode()
    need(before==b'each pulse has the supplied bounded involution generator' and after==b'each pulse has its specified supplied bounded Hermitian generator','Required phrase differs')
    wrapper=osource('CURRENT_WRAPPER.md');candidate=osource('CANDIDATE_NOTE.md')
    need(old_wrapper.count(before)==old_candidate.count(before)==1 and wrapper==old_wrapper.replace(before,after,1) and candidate==old_candidate.replace(before,after,1),'One-phrase overlay does not reconstruct')
    need(sha(wrapper)=='9baf2243db8397af46490583d2a57ddfd4d145bb7a9f4cc7243e0f8b1171da97' and sha(candidate)=='a0c9f3c918a969cea3bb1d110e845a69a469b63e5fe85c7a886b04dcecff3419','Corrected candidate differs')
    x=correction['new_proof_span'];i,j=x['byte_start_0'],x['byte_end_exclusive']
    need(candidate[i:j]==b and candidate.count(b)==1 and candidate[len(wrapper):]==old_candidate[len(old_wrapper):] and correction['proof_byte_edits']==0,'Corrected complete proof differs')
    need(candidate[:i].count(b'\n')+1==x['line_start_1'] and candidate[:j].count(b'\n')==x['line_end_1'],'Corrected extraction lines differ')
    for name,a,c,an,cn in [('WRAPPER',old_wrapper,wrapper,'original/wrappers/CURRENT_WRAPPER.md','overlay/CURRENT_WRAPPER.md'),('CANDIDATE',old_candidate,candidate,'original/CANDIDATE_NOTE.md','overlay/CANDIDATE_NOTE.md')]:
        need(osource('diffs/'+name+'.diff')==diff(a,c,an,cn),'Complete framing correction diff differs')
    cores=[b]
    edits=pinned('PUBLICATION_EDITS.json',EDITS_SHA,'Publication transformation changed')
    need(edits['source_freeze_sha256']==SOURCE_FREEZE_SHA and edits['source_framing_overlay_seal_sha256']==overlay['seal_sha256'] and edits['mathematical_body_edits']==[] and len(edits['notes'])==1,'Publication scope differs')
    note=edits['notes'][0];rendered_wrapper=wrapper
    for t in edits['wrapper_replacements']:
        a,b=t['original'].encode(),t['rendered'].encode()
        need(t['scope']=='publication metadata or current source-status pointer only' and rendered_wrapper.count(a)==1,'Wrapper replacement differs');rendered_wrapper=rendered_wrapper.replace(a,b,1)
    published=edits['frontmatter'].encode()+rendered_wrapper+candidate[len(wrapper):];actual=read(note['note'])
    need(actual==published and sha(actual)==note['published_sha256'] and len(actual)==note['published_bytes'],'Published source does not reconstruct')
    need(len(note['complete_bodies'])==1,'Published proof count differs')
    for x,b in zip(note['complete_bodies'],cores):
        i,j=x['byte_start_inclusive'],x['byte_end_exclusive']
        need(actual[i:j]==b and actual.count(b)==1 and sha(b)==x['sha256'] and x['body_edits']==[],'Published whole proof differs')
        need(actual[:i].count(b'\n')+1==x['line_start_inclusive'] and actual[:j].count(b'\n')==x['line_end_inclusive'],'Published proof lines differ')
    for r,a,b in [(note,candidate,actual),(edits['wrapper_diff'],wrapper,rendered_wrapper)]:
        z=read(PACKET+'/'+r['diff']);d=gzip.decompress(z)
        need(sha(z)==r['diff_stored_sha256'] and sha(d)==r['diff_sha256'] and d==diff(a,b,r['fromfile'],r['tofile']),'Full publication diff differs')
    bindings=pinned('PARENT_BINDINGS.json',PARENTS_SHA,'Parent bindings changed');parents=bindings['parents']
    need(bindings['binding_complete'] and bindings['publication_ancestry_is_not_mathematical_dependency'] and not bindings['history_theorem_imported'],'Current parent binding unresolved')
    need([{'key':p['key'],'role_class':p['role_class'],'imported_theorem_result':p['imported_theorem_result']} for p in parents]==bindings['required_roles'],'Citation roles differ')
    for p in parents:
        b=read(p['path']);need(sha(archived(p['archive_alias']))==p.get('original_published_sha256',p['published_sha256']) and sha(b)==p['published_sha256'] and len(b)==p['bytes'],'Current cited source changed')
        need(actual.decode().count(p['markdown'])==1,'Scientific or attribution citation differs')
    for x in bindings['canonical_core_maps']:
        b=read(x['canonical_path']);core=archived(x['source_path'])
        need(sha(core)==x['source_sha256'] and b[x['byte_start_inclusive']:x['byte_end_exclusive']]==core and b.count(core)==1 and x['body_edits']==[],'Canonical relied core differs')
    need(re.findall(r'\[[^\]]*\]\(([^)\s#]+\.md)(?:#[^)]*)?\)',actual.decode())==bindings['all_markdown_note_targets'],'Recognized Markdown targets differ')
    graph=pinned('CLAIM_REGISTRY_ADDITIONS.json',GRAPH_SHA,'Graph proposal changed');deps=[p['claim_id'] for p in parents]
    need(graph['binding_complete'] and graph['nodes'][0]['claim_id']==CLAIM and graph['nodes'][0]['deps']==deps
         and graph['direct_edges']==[{'from':CLAIM,'to':d} for d in deps] and graph['new_roots']==[]
         and graph['expected_delta']=={'nodes':1,'edges':len(deps),'roots':0},'Citation-derived graph proposal differs')
    status=pinned('SOURCE_REVIEW_STATUS.json',STATUS_SHA,'Review scope changed')
    for r in status['prior_acceptances']:
        raw=read(PACKET+'/'+r['file']);need(sha(raw)==r['sha256'] and json.loads(raw)==r['verbatim'],'Earlier acceptance changed')
    need(status['mathematical_bodies_accepted'] and status['mathematical_core_edits']==0 and not status['new_independent_mathematical_review']
         and not status['retained_audit_status'] and not status['no_go_packet_pass'],'Review limitation differs')
    need(status['historical_imported_roles_separated_from_current_status'] and status['global_history_21_local_terminal_23_separated'],'Current historical/physical scope differs')
    for name,p in EXTRA_PINS.items():
        b=read(name);need(sha(b)==p['sha256'] and len(b)==p['bytes'],'Additional publication integrity input changed')
    need(set(reads)==set(AUDIT_INPUT_PATHS) and len(AUDIT_INPUT_PATHS)==len(set(AUDIT_INPUT_PATHS)),'Declared read closure differs')
    return {'result':'source_identities_and_reconstruction_match','claim_id':CLAIM,'meaning':'Byte integrity only; no mathematical calculation, proof or audit executed.',
        'mathematical_operations_executed':False,'mathematical_predicates_executed':0,'scientific_mutations_executed':0,
        'no_go_packet_pass_supplied_by_tool':False,'independent_review_supplied_by_tool':False,
        'external_scientific_parent_reads':[p['path'] for p in parents if p['imported_theorem_result']],
        'attribution_reads':[p['path'] for p in parents if not p['imported_theorem_result']]}
def main():
    print(json.dumps(verify(Path(__file__).resolve().parents[1]),sort_keys=True))
    print('per_element: checked and not executed — source integrity only; no operator algebra was evaluated.')
    print('per_site: checked and not executed — source integrity only; no local norm or support count was computed.')
    print('per_mode: checked and not executed — source integrity only; no code existence or parity theorem was evaluated.')
    print('per_block: checked and not executed — source integrity only; no weak-background or trace estimate was evaluated.')
    print('lattice_wide: checked and not executed — source integrity only; no all-volume or native theorem was verified.')
if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'result':'identity_verification_incomplete','error':str(error),'mathematical_operations_executed':False,
            'mathematical_predicates_executed':0,'scientific_mutations_executed':0}),file=sys.stderr)
        raise SystemExit(1)
